    /// <summary>heapq: a binary min-heap in a list, CPython's algorithm (the same list layout, so printing a heap matches).</summary>
    internal static class heapq
    {
        static bool Lt<T>(IComparer<T> c, T a, T b) => c.Compare(a, b) < 0;

        public static void heappush<T>(List<T> heap, T item)
        {
            heap.Add(item);
            SiftDown(heap, 0, heap.Count - 1, Builtins.PyComparer<T>());
        }

        public static T heappop<T>(List<T> heap)
        {
            if (heap.Count == 0) throw new ArgumentOutOfRangeException(nameof(heap), "index out of range");
            var last = heap[heap.Count - 1];
            heap.RemoveAt(heap.Count - 1);
            if (heap.Count == 0) return last;
            var result = heap[0];
            heap[0] = last;
            SiftUp(heap, 0, Builtins.PyComparer<T>());
            return result;
        }

        public static T heapreplace<T>(List<T> heap, T item)
        {
            if (heap.Count == 0) throw new ArgumentOutOfRangeException(nameof(heap), "index out of range");
            var result = heap[0];
            heap[0] = item;
            SiftUp(heap, 0, Builtins.PyComparer<T>());
            return result;
        }

        public static T heappushpop<T>(List<T> heap, T item)
        {
            var c = Builtins.PyComparer<T>();
            if (heap.Count > 0 && Lt(c, heap[0], item))
            {
                (item, heap[0]) = (heap[0], item);
                SiftUp(heap, 0, c);
            }
            return item;
        }

        public static void heapify<T>(List<T> x)
        {
            var c = Builtins.PyComparer<T>();
            for (int i = x.Count / 2 - 1; i >= 0; i--) SiftUp(x, i, c);
        }

        static void SiftDown<T>(List<T> heap, int start, int pos, IComparer<T> c)
        {
            var item = heap[pos];
            while (pos > start)
            {
                int parentPos = (pos - 1) >> 1;
                var parent = heap[parentPos];
                if (Lt(c, item, parent)) { heap[pos] = parent; pos = parentPos; continue; }
                break;
            }
            heap[pos] = item;
        }

        static void SiftUp<T>(List<T> heap, int pos, IComparer<T> c)
        {
            int end = heap.Count, start = pos;
            var item = heap[pos];
            int child = 2 * pos + 1;
            while (child < end)
            {
                int right = child + 1;
                if (right < end && !Lt(c, heap[child], heap[right])) child = right;
                heap[pos] = heap[child];
                pos = child;
                child = 2 * pos + 1;
            }
            heap[pos] = item;
            SiftDown(heap, start, pos, c);
        }

        // nlargest / nsmallest: documented as sorted(iterable, key=key, reverse=...)[:n]
        public static List<T> nlargest<T>(long n, IEnumerable<T> iterable) => Builtins.sorted(iterable, reverse: true).Take((int)Math.Max(0, n)).ToList();
        public static List<T> nlargest<T, K>(long n, IEnumerable<T> iterable, Func<T, K> key) => Builtins.sorted(iterable, key, reverse: true).Take((int)Math.Max(0, n)).ToList();
        public static List<T> nsmallest<T>(long n, IEnumerable<T> iterable) => Builtins.sorted(iterable).Take((int)Math.Max(0, n)).ToList();
        public static List<T> nsmallest<T, K>(long n, IEnumerable<T> iterable, Func<T, K> key) => Builtins.sorted(iterable, key).Take((int)Math.Max(0, n)).ToList();

        /// <summary>merge(*iterables): sorted inputs merged lazily; equal items come from the earlier input first.</summary>
        public static IEnumerable<T> merge<T>(params IEnumerable<T>[] iterables) => Merge(iterables, (Func<T, T>)(x => x), false);
        public static IEnumerable<T> merge<T, K>(IEnumerable<T> a, IEnumerable<T> b, Func<T, K> key, bool reverse = false) => Merge(new[] { a, b }, key, reverse);

        static IEnumerable<T> Merge<T, K>(IEnumerable<T>[] iterables, Func<T, K> key, bool reverse)
        {
            var c = Builtins.PyComparer<K>();
            var its = iterables.Select(x => x.GetEnumerator()).ToList();
            var live = new List<int>();
            for (int i = 0; i < its.Count; i++) if (its[i].MoveNext()) live.Add(i);
            while (live.Count > 0)
            {
                int best = live[0];
                foreach (int i in live.Skip(1))
                {
                    int cmp = c.Compare(key(its[i].Current), key(its[best].Current));
                    if (reverse ? cmp > 0 : cmp < 0) best = i;
                }
                yield return its[best].Current;
                if (!its[best].MoveNext()) live.Remove(best);
            }
        }
    }

    /// <summary>bisect: binary search and insertion in a sorted list (key= is applied to the items, and for insort to x too).</summary>
    internal static class bisect_
    {
        static int Hi<T>(IList<T> a, long? hi) => hi is long h ? (int)h : a.Count;

        public static long bisect_left<T>(IList<T> a, T x, long lo = 0, long? hi = null)
        {
            if (lo < 0) throw new ArgumentException("lo must be non-negative");
            var c = Builtins.PyComparer<T>(); int l = (int)lo, h = Hi(a, hi);
            while (l < h) { int mid = (l + h) / 2; if (c.Compare(a[mid], x) < 0) l = mid + 1; else h = mid; }
            return l;
        }
        public static long bisect_right<T>(IList<T> a, T x, long lo = 0, long? hi = null)
        {
            if (lo < 0) throw new ArgumentException("lo must be non-negative");
            var c = Builtins.PyComparer<T>(); int l = (int)lo, h = Hi(a, hi);
            while (l < h) { int mid = (l + h) / 2; if (c.Compare(x, a[mid]) < 0) h = mid; else l = mid + 1; }
            return l;
        }
        public static long bisect<T>(IList<T> a, T x, long lo = 0, long? hi = null) => bisect_right(a, x, lo, hi);

        public static long bisect_left<T, K>(IList<T> a, K x, Func<T, K> key, long lo = 0, long? hi = null)
        {
            var c = Builtins.PyComparer<K>(); int l = (int)lo, h = Hi(a, hi);
            while (l < h) { int mid = (l + h) / 2; if (c.Compare(key(a[mid]), x) < 0) l = mid + 1; else h = mid; }
            return l;
        }
        public static long bisect_right<T, K>(IList<T> a, K x, Func<T, K> key, long lo = 0, long? hi = null)
        {
            var c = Builtins.PyComparer<K>(); int l = (int)lo, h = Hi(a, hi);
            while (l < h) { int mid = (l + h) / 2; if (c.Compare(x, key(a[mid])) < 0) h = mid; else l = mid + 1; }
            return l;
        }
        public static long bisect<T, K>(IList<T> a, K x, Func<T, K> key, long lo = 0, long? hi = null) => bisect_right(a, x, key, lo, hi);

        public static void insort_left<T>(List<T> a, T x, long lo = 0, long? hi = null) => a.Insert((int)bisect_left(a, x, lo, hi), x);
        public static void insort_right<T>(List<T> a, T x, long lo = 0, long? hi = null) => a.Insert((int)bisect_right(a, x, lo, hi), x);
        public static void insort<T>(List<T> a, T x, long lo = 0, long? hi = null) => insort_right(a, x, lo, hi);
        public static void insort_left<T, K>(List<T> a, T x, Func<T, K> key, long lo = 0, long? hi = null) => a.Insert((int)bisect_left(a, key(x), key, lo, hi), x);
        public static void insort_right<T, K>(List<T> a, T x, Func<T, K> key, long lo = 0, long? hi = null) => a.Insert((int)bisect_right(a, key(x), key, lo, hi), x);
        public static void insort<T, K>(List<T> a, T x, Func<T, K> key, long lo = 0, long? hi = null) => insort_right(a, x, key, lo, hi);
    }

    /// <summary>copy: shallow and deep copies of Python containers and Typhon objects (__copy__ / __deepcopy__ are honoured).</summary>
    internal static class copy_
    {
        static readonly MethodInfo Clone = typeof(object).GetMethod("MemberwiseClone", BindingFlags.Instance | BindingFlags.NonPublic)!;

        public static T copy<T>(T x) => (T)Shallow(x)!;
        public static T deepcopy<T>(T x) => (T)Deep(x, new Dictionary<object, object?>(ReferenceEqualityComparer.Instance))!;
        public static T deepcopy<T>(T x, IDictionary<object, object?> memo) => (T)Deep(x, memo)!;

        static bool Immutable(object? o) => o is null || o is string || o is PyFunction || o is Type || o is Delegate || o is Fraction ||
                                             o.GetType().IsPrimitive || o is decimal || o is System.Numerics.BigInteger || o is Enum || o is PyRange;

        static object? Shallow(object? o)
        {
            if (Immutable(o) || o is System.Runtime.CompilerServices.ITuple && o.GetType().IsValueType || o is IPyTuple) return o;
            var t = o!.GetType();
            if (t.GetMethod("__copy__", Type.EmptyTypes) is MethodInfo own) return own.Invoke(o, null);
            if (o is Array arr) return arr.Clone();
            if (t.GetMethod("copy", Type.EmptyTypes) is MethodInfo cp && cp.ReturnType != typeof(void)) return cp.Invoke(o, null);
            if (t.IsGenericType && (t.GetGenericTypeDefinition() == typeof(List<>) || t.GetGenericTypeDefinition() == typeof(HashSet<>)))
                return Activator.CreateInstance(t, o);
            if (o is IDictionary d && t.GetConstructor(Type.EmptyTypes) != null)
            {
                var n = (IDictionary)Activator.CreateInstance(t)!;
                var en = d.GetEnumerator();
                while (en.MoveNext()) n[en.Key] = en.Value;
                return n;
            }
            return Clone.Invoke(o, null); // a Typhon object: a new object with the same attribute values
        }

        static object? Deep(object? o, IDictionary<object, object?> memo)
        {
            if (Immutable(o)) return o;
            if (memo.TryGetValue(o!, out var done)) return done;
            var t = o!.GetType();
            if (t.GetMethod("__deepcopy__", new[] { typeof(IDictionary<object, object?>) }) is MethodInfo own) return own.Invoke(o, new object[] { memo });
            if (o is System.Runtime.CompilerServices.ITuple tup && t.IsValueType)
            {
                var items = new object?[tup.Length];
                for (int i = 0; i < items.Length; i++) items[i] = Deep(tup[i], memo);
                return Activator.CreateInstance(t, items);
            }
            if (o is Array arr)
            {
                var n = (Array)arr.Clone();
                memo[o] = n;
                for (int i = 0; i < n.Length; i++) n.SetValue(Deep(arr.GetValue(i), memo), i);
                return n;
            }
            if (o is IList list && t.GetConstructor(Type.EmptyTypes) is ConstructorInfo lc)
            {
                var n = (IList)lc.Invoke(null);
                memo[o] = n;
                foreach (var x in list) n.Add(Deep(x, memo));
                return n;
            }
            if (o is IDictionary dict && t.GetConstructor(Type.EmptyTypes) is ConstructorInfo dc)
            {
                var n = (IDictionary)dc.Invoke(null);
                memo[o] = n;
                var en = dict.GetEnumerator();
                while (en.MoveNext()) n[Deep(en.Key, memo)!] = Deep(en.Value, memo);
                return n;
            }
            if (t.IsGenericType && t.GetGenericTypeDefinition() == typeof(HashSet<>))
            {
                dynamic n = Activator.CreateInstance(t)!;
                memo[o] = n;
                foreach (var x in (IEnumerable)o) n.Add((dynamic?)Deep(x, memo));
                return n;
            }
            if (o is IPyTuple)
            {
                // a computed-length tuple of T: its items deep-copied into a T[]
                var elem = t.GetGenericArguments()[0];
                var items = ((IEnumerable)o).Cast<object?>().Select(x => Deep(x, memo)).ToArray();
                var typed = Array.CreateInstance(elem, items.Length);
                for (int i = 0; i < items.Length; i++) typed.SetValue(items[i], i);
                return Activator.CreateInstance(t, typed);
            }
            // a Typhon object: a new object whose attributes are deep copies
            var copy = Clone.Invoke(o, null)!;
            memo[o] = copy;
            for (var k = t; k != null && k != typeof(object); k = k.BaseType)
                foreach (var f in k.GetFields(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.DeclaredOnly))
                    f.SetValue(copy, Deep(f.GetValue(o), memo));
            return copy;
        }
    }

